        lines.push("", `### ${safeMarkdown(outcome.error.title)}`, "", `**Code:** \`${outcome.error.code}\` · **Phase:** \`${outcome.error.phase}\``, "", safeMarkdown(outcome.error.message), "", `**Next step:** ${safeMarkdown(outcome.error.guidance)}`);
